private data class PaymentVectorPath(
    val data: String,
    val fill: Brush,
    val fillType: PathFillType,
)

private fun paymentVector(
    name: String,
    defaultWidth: Float,
    defaultHeight: Float,
    viewportWidth: Float,
    viewportHeight: Float,
    autoMirror: Boolean,
    paths: List<PaymentVectorPath>,
): ImageVector = ImageVector.Builder(
    name = name,
    defaultWidth = defaultWidth.dp,
    defaultHeight = defaultHeight.dp,
    viewportWidth = viewportWidth,
    viewportHeight = viewportHeight,
    autoMirror = autoMirror,
).apply {
    paths.forEach { vectorPath ->
        addPath(
            pathData = PathParser().parsePathString(vectorPath.data).toNodes(),
            pathFillType = vectorPath.fillType,
            fill = vectorPath.fill,
        )
    }
}.build()
